function authChoice(
  providerId: string,
  appGuidedAuth: "oauth" | "device-code",
  choiceLabel = "Fixture sign-in",
) {
  return {
    pluginId: providerId,
    providerId,
    methodId: "fixture-login",
    choiceId: "fixture-login",
    choiceLabel,
    appGuidedAuth,
