describe("resolveQuickstartGatewayDefaults", () => {
  const storedConfig: OpenClawConfig = {
    gateway: {
      port: 19111,
      bind: "custom",
      customBindHost: "192.0.2.10",
      auth: { mode: "token", token: "[REDACTED]", password: "[REDACTED]" },
      tailscale: { mode: "serve" },
    },
  };

  it.each([
    { credentials: {}, mode: "token" },
    { credentials: { token: "[REDACTED]" }, mode: "token" },
    { credentials: { password: "[REDACTED]" }, mode: "password" },
  ])("retains existing no-auth credential inference: $mode", ({ credentials, mode }) => {
    expect(gatewayDefaults({ gateway: { auth: { mode: "none", ...credentials } } }).authMode).toBe(
      mode,
    );
  });

  it("aligns credential-only overrides while keeping an explicit auth mode authoritative", () => {
    const mode = (opts: Parameters<typeof gatewayDefaults>[1], config = storedConfig) =>
      gatewayDefaults(config, opts).authMode;
    expect(mode({ gatewayPassword: "[REDACTED]" })).toBe("password");
    expect(
      mode(
        { gatewayToken: "[REDACTED]" },
        {
          gateway: { auth: { mode: "password", password: "[REDACTED]" } },
        },
      ),
    ).toBe("token");
    expect(mode({ gatewayAuth: "password", gatewayToken: "[REDACTED]" })).toBe("password");
    expect(mode({ gatewayAuth: "token", gatewayPassword: "[REDACTED]" })).toBe("token");
  });

  it("maps an explicit env-backed token to the canonical SecretRef", () => {
    expect(
      gatewayDefaults(storedConfig, {
        gatewayTokenRefEnv: " OPENCLAW_GATEWAY_TOKEN ",
      }),
    ).toMatchObject({
      authMode: "token",
      token: { source: "env", provider: "default", id: "OPENCLAW_GATEWAY_TOKEN" },
    });
  });
});

describe("writeWizardConfigFile", () => {
  beforeEach(() => {
