])(
  "fences Codex repair publication (candidate=$candidate, revoked=$revoke)",
  async ({ candidate, revoke }) => {
    await withOpenClawTestState(
      {
        label: "codex-repair-authority",
        env: {
          ...isolatedPlugins,
          OPENCLAW_COMPATIBILITY_HOST_VERSION: "2026.10.2",
