} from "./defaults.js";
import { authContext, GIB, mocks, modelPath, tempRoot } from "./setup.test-support.js";

const { runLlamaCppSetup } = await import("./setup.js");

function authoredChatContext(source: string, confirm = true): ProviderAuthContext {
  const ctx = authContext(confirm);
  const model = buildLlamaCppModel({ id: "selected", name: "Selected GGUF", source });
  ctx.config.models = {
    providers: {
      [LLAMA_CPP_PROVIDER_ID]: {
        baseUrl: "http://127.0.0.1:19432/v1",
        params: { modelCacheDir: tempRoot },
        localService: { command: path.join(tempRoot, "llama-server") },
        models: [buildLlamaCppModel({ id: "other", name: "Other GGUF", source: modelPath }), model],
      },
    },
  };
  ctx.config.agents = { defaults: { model: { primary: "llama-cpp/selected" } } };
  return ctx;
}

describe("llama.cpp authored model setup", () => {
  it.each([
    "llama-cpp/selected",
    "Chosen",
    "llama-cpp/Chosen",
    "llama-cpp/selected@llama-cpp:default",
  ])("keeps the selected model when the primary is %s", async (primary) => {
    const ctx = authoredChatContext(DEFAULT_LLAMA_CPP_MODEL_URI);
    await fs.writeFile(modelPath, "GGUF");
    ctx.config.agents = {
      defaults: {
        model: { primary },
        models: { "llama-cpp/selected": { alias: "Chosen" } },
      },
    };

    const result = await runLlamaCppSetup(ctx);

    expect(result.defaultModel).toBe("llama-cpp/selected");
    expect(result.configPatch?.models?.providers?.[LLAMA_CPP_PROVIDER_ID]?.models[0]?.id).toBe(
      "selected",
    );
  });

  it.each([
    {
      source:
        "hf:unsloth/Qwen3.5-4B-GGUF/Qwen3.5-4B-Q4_K_M.gguf#e87f176479d0855a907a41277aca2f8ee7a09523",
      size: "2.7 GB",
    },
    { source: "hf:owner/repo/custom.gguf", size: "1.2 GB" },
    { source: "https://models.example/custom.gguf", size: "1.2 GB" },
    { source: "https://models.example/no-head.gguf", size: "size unknown", headStatus: 405 },
    { source: "https://models.example/broken-head.gguf", size: "size unknown", headError: true },
  ])(
    "offers the selected uncached $source instead of the hardware recommendation",
    async ({ source, size, headStatus, headError }) => {
      vi.mocked(os.totalmem).mockReturnValue(512 * GIB);
      const ctx = authoredChatContext(source);
      mocks.downloadFetch.mockImplementation(async () => {
        if (headError) {
          throw new Error("HEAD connection closed");
        }
        return {
          response: source.startsWith("https:")
            ? new Response(null, {
                status: headStatus,
                headers: { "content-length": "1200000000" },
              })
            : Response.json([
                { path: "custom.gguf", size: 1_200_000_000, lfs: { oid: "a".repeat(64) } },
              ]),
          release: vi.fn(),
        };
      });
      const selected = ctx.config.models?.providers?.[LLAMA_CPP_PROVIDER_ID]?.models[1];

      const result = await runLlamaCppSetup(ctx);

      expect(ctx.prompter.confirm).toHaveBeenCalledExactlyOnceWith(
        expect.objectContaining({
          message: expect.stringContaining(`Download Selected GGUF (${size})`),
          initialValue: false,
        }),
      );
      expect(result.defaultModel).toBe("llama-cpp/selected");
      expect(result.configPatch?.models?.providers?.[LLAMA_CPP_PROVIDER_ID]?.models[0]).toEqual(
        selected,
      );
      expect(mocks.ensureModel).toHaveBeenCalledWith(
        expect.objectContaining({ source, download: true }),
      );
      expect(mocks.prepareServer).toHaveBeenCalledWith(
        expect.objectContaining({ chatModel: expect.objectContaining({ id: "selected" }) }),
      );
    },
  );

  it("leaves an authored route unchanged when its download is declined", async () => {
    const ctx = authoredChatContext(DEFAULT_LLAMA_CPP_MODEL_URI, false);
    ctx.config.memory = { search: { provider: "local" } };
    const before = structuredClone(ctx.config);

    await expect(runLlamaCppSetup(ctx)).resolves.toEqual({ profiles: [] });

    expect(ctx.prompter.confirm).toHaveBeenCalledExactlyOnceWith(
      expect.objectContaining({ message: expect.stringContaining("Download Selected GGUF") }),
    );
    expect(ctx.config).toEqual(before);
    expect(mocks.ensureServerInstalled).not.toHaveBeenCalled();
    expect(mocks.ensureModel).not.toHaveBeenCalledWith(expect.objectContaining({ download: true }));
    expect(mocks.prepareServer).not.toHaveBeenCalled();
  });

  it.each([
    ["hf:invalid", "Invalid Hugging Face model URI"],
    ["https://models.example/model.txt", "Remote model URL must name a GGUF file"],
    ["ftp://models.example/model.gguf", "Unsupported remote model URI"],
  ])("explains why the authored source %s cannot be used", async (source, reason) => {
    const ctx = authoredChatContext(source);

    await expect(runLlamaCppSetup(ctx)).resolves.toEqual({ profiles: [] });

    expect(ctx.prompter.note).toHaveBeenCalledWith(
      expect.stringContaining(reason),
      "Setup skipped",
    );
    expect(ctx.prompter.confirm).not.toHaveBeenCalled();
    expect(mocks.ensureServerInstalled).not.toHaveBeenCalled();
  });
});

import { expect, it, vi } from "vitest";
import { bindMemoryProvider } from "../../plugins/memory-provider-adapter.js";
import { createDeferredCore } from "../../shared/deferred.js";
import { runPostCompactionSideEffects } from "./compaction-hooks.js";

const {
  emitSessionTranscriptUpdate,
  getMemorySearchManager,
  getMemoryProvider,
  memoryKind,
  prepareRead,
} = vi.hoisted(() => ({
  emitSessionTranscriptUpdate: vi.fn(),
  getMemorySearchManager: vi.fn(),
  getMemoryProvider: vi.fn(),
  memoryKind: { native: false },
  prepareRead: vi.fn(),
}));
vi.mock("../../sessions/transcript-events.js", () => ({ emitSessionTranscriptUpdate }));
// mock-isolation: Keep acquisition under the test's control without loading the plugin registry.
vi.mock("../../plugins/memory-runtime.js", () => ({
  getActiveMemorySearchManagerCore: getMemorySearchManager,
  getActiveMemoryProviderCore: getMemoryProvider,
}));
// mock-isolation: Select the native or legacy lifecycle without changing process-wide plugin state.
vi.mock("../../plugins/memory-state.js", () => ({
  resolveLoadedMemoryProviderKind: () => (memoryKind.native ? "native" : undefined),
}));
// mock-isolation: Exercise the real provider adapter with a controlled pending audience publication.
vi.mock("../../plugins/memory-audience.js", () => ({
  prepareMemoryCallerRead: prepareRead,
  assertMemoryCallerCurrent: (context: { assertCurrent: () => void }) => context.assertCurrent(),
}));
// mock-isolation: Enable session indexing without loading embedding providers or user configuration.
vi.mock("../memory-search.js", () => ({
  resolveMemorySearchIndexConfig: () => ({
    sources: ["sessions"],
    sync: { sessions: { postCompactionForce: true } },
  }),
}));

const sessionFile = "synthetic-compaction";
const session = {
  agentId: "main",
  sessionId: "compaction-handoff",
  sessionKey: "agent:main:compaction-handoff",
};

it.each(["allow", "refuse"] as const)(
  "awaits post-compaction authority before publishing (%s)",
  async (decision) => {
    emitSessionTranscriptUpdate.mockClear();
    const entered = createDeferredCore();
    const authority = createDeferredCore();
    const pending = runPostCompactionSideEffects({
      sessionFile,
      assertActive: async () => {
        entered.resolve();
        await authority.promise;
      },
    });
    await entered.promise;
    expect(emitSessionTranscriptUpdate).not.toHaveBeenCalled();
    if (decision === "refuse") {
      const failure = new Error("Compaction owner retired");
      const rejected = expect(pending).rejects.toBe(failure);
      authority.reject(failure);
      await rejected;
      expect(emitSessionTranscriptUpdate).not.toHaveBeenCalled();
    } else {
      authority.resolve();
      await pending;
      expect(emitSessionTranscriptUpdate).toHaveBeenCalledExactlyOnceWith({
        sessionFile,
        sessionKey: undefined,
      });
    }
  },
);

it.each([
  { native: false, revoked: false },
  { native: false, revoked: true },
  { native: true, revoked: false },
  { native: true, revoked: true },
])(
  "hands async indexing to its owner before foreground retirement (native=$native, revoked=$revoked)",
  async ({ native, revoked }) => {
    memoryKind.native = native;
    const managerRequested = createDeferredCore();
    const managerReady = createDeferredCore();
    const authorityAfterOpen = createDeferredCore();
    const finishSync = createDeferredCore();
    const providerClosed = createDeferredCore();
    const admissionEntered = createDeferredCore();
    const admissionReady = createDeferredCore();
    let managerOpened = false;
    let callerActive = true;
    const sync = vi.fn(() => finishSync.promise);
    const close = vi.fn(async () => providerClosed.resolve());
    const assertCurrent = () => {
      if (!callerActive) {
        throw new Error("compaction caller retired");
      }
    };
    prepareRead.mockReset();
    if (native) {
      prepareRead.mockImplementationOnce(() => {
        admissionEntered.resolve();
        return admissionReady.promise;
      });
    }
    const acquire = async () => {
      managerRequested.resolve();
      await managerReady.promise;
      managerOpened = true;
      return native
        ? {
            provider: bindMemoryProvider(
              {
                capabilities: {
                  sources: ["sessions"],
                  candidates: [],
                  pagination: false,
                  projectFilter: false,
                },
                search: async () => ({ hits: [] }),
                get: async () => ({ status: "not_found" }),
                health: async () => ({ status: "ready" }),
                refresh: sync,
                close,
              },
              "test-memory",
              { authority: { kind: "host", operation: "post-compaction-refresh" }, assertCurrent },
            ),
          }
        : { manager: { sync } };
    };
    (native ? getMemoryProvider : getMemorySearchManager).mockImplementationOnce(acquire);
    const foreground = runPostCompactionSideEffects({
      config: { agents: { defaults: { compaction: { postIndexSync: "async" } } } },
      sessionFile,
      ...session,
      assertActive: () => {
        if (managerOpened) {
          authorityAfterOpen.resolve();
        }
        assertCurrent();
      },
    }).then(() => {
      callerActive = false;
    });
    try {
      await managerRequested.promise;
      if (revoked && !native) {
        callerActive = false;
      }
      const completion = revoked
        ? expect(foreground).rejects.toThrow("compaction caller retired")
        : foreground;
      managerReady.resolve();
      if (native) {
        await admissionEntered.promise;
        // Queue the assertion after any foreground completion already admitted by the caller.
        await Promise.resolve();
        await Promise.resolve();
        expect(callerActive).toBe(true);
        expect(sync).not.toHaveBeenCalled();
        if (revoked) {
          callerActive = false;
        }
        admissionReady.resolve();
      }
      await completion;
      await authorityAfterOpen.promise;
      if (revoked) {
        expect(sync).not.toHaveBeenCalled();
      } else {
        if (native) {
          expect(sync).toHaveBeenCalledExactlyOnceWith();
          expect(close).not.toHaveBeenCalled();
        } else {
          expect(sync).toHaveBeenCalledExactlyOnceWith({
            reason: "post-compaction",
            sessions: [session],
          });
        }
        finishSync.resolve();
        await sync.mock.results[0]?.value;
      }
      if (native) {
        await providerClosed.promise;
        expect(close).toHaveBeenCalledOnce();
      }
    } finally {
      managerReady.resolve();
      admissionReady.resolve();
      finishSync.resolve();
      await foreground.catch(() => {});
      memoryKind.native = false;
    }
  },
);

it("awaits archive-file memory sync before settling", async () => {
  memoryKind.native = false;
  getMemorySearchManager.mockClear();
  const syncStarted = createDeferredCore<unknown>();
  const syncRelease = createDeferredCore();
  const sync = vi.fn(async (params?: unknown) => {
    syncStarted.resolve(params);
    await syncRelease.promise;
  });
  getMemorySearchManager.mockResolvedValueOnce({ manager: { sync } });
  let settled = false;
  const resultPromise = runPostCompactionSideEffects({
    config: { agents: { defaults: { compaction: { postIndexSync: "await" } } } },
    agentId: "main",
    sessionFile,
    sessionKey: "agent:main:sync-mode",
  });
  void resultPromise.then(() => {
    settled = true;
  });
  try {
    await expect(syncStarted.promise).resolves.toEqual({
      archiveFiles: [sessionFile],
      reason: "post-compaction",
    });
    expect(settled).toBe(false);
    syncRelease.resolve();
    await resultPromise;
    expect(settled).toBe(true);
  } finally {
    syncRelease.resolve();
    await resultPromise;
  }
});

import { spawnSync } from "node:child_process";
import { mkdirSync, readFileSync, symlinkSync, writeFileSync } from "node:fs";
import path from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { parse } from "yaml";
import { useAutoCleanupTempDirTracker } from "../helpers/temp-dir.js";

const tempDirs = useAutoCleanupTempDirTracker(afterEach);
const ripgrep = parse(readFileSync(".github/actions/setup-ripgrep/action.yml", "utf8"));
const browser = parse(readFileSync(".github/actions/setup-playwright-chromium/action.yml", "utf8"));

describe.skipIf(process.platform === "win32")("CI browser and grep setup", () => {
  it.each([true, false])("reuses runner rg=%s and refuses corrupt downloads", (installed) => {
    const root = tempDirs.make("openclaw-grep-setup-");
    const bin = path.join(root, "bin");
    mkdirSync(bin);
    const githubPath = path.join(root, "github-path");
    writeFileSync(githubPath, "");
    // Isolate PATH so a developer's rg cannot hide the cold path.
    for (const command of ["mktemp", "tar"]) {
      const location = spawnSync("/bin/bash", ["-c", `command -v ${command}`], {
        encoding: "utf8",
      }).stdout.trim();
      symlinkSync(location, path.join(bin, command));
    }
    if (process.platform === "darwin") {
      // macOS's sha256sum is absent or BSD-only; shasum owns the same byte check.
      writeFileSync(path.join(bin, "sha256sum"), "#!/bin/bash\nexec /usr/bin/shasum -a 256 -c\n", {
        mode: 0o755,
      });
    } else {
      const checksumTool = spawnSync("/bin/bash", ["-c", "command -v sha256sum"], {
        encoding: "utf8",
      }).stdout.trim();
      symlinkSync(checksumTool, path.join(bin, "sha256sum"));
    }
    writeFileSync(
      path.join(bin, "curl"),
      '#!/bin/bash\nwhile [[ "$1" != "--output" ]]; do shift; done\nshift\nprintf corrupt > "$1"\n',
      { mode: 0o755 },
    );
    if (installed) {
      writeFileSync(path.join(bin, "rg"), "#!/bin/bash\necho existing-rg\n", { mode: 0o755 });
    }
    const result = spawnSync("/bin/bash", ["-euo", "pipefail", "-c", ripgrep.runs.steps[0].run], {
      encoding: "utf8",
      env: {
        ...process.env,
        PATH: bin,
        RUNNER_OS: "Linux",
        RUNNER_ARCH: "X64",
        RUNNER_TEMP: root,
        GITHUB_PATH: githubPath,
      },
    });
    if (installed) {
      expect(result.status).toBe(0);
      expect(result.stdout).toContain("existing-rg");
    } else {
      expect(result.status).not.toBe(0);
      expect(result.stdout + result.stderr).toContain("FAILED");
    }
    expect(readFileSync(githubPath, "utf8")).toBe("");
  });

  it.each(["X64", "ARM64"])("keys Chromium by installed target version and %s", (arch) => {
    const root = tempDirs.make("openclaw-browser-cache-");
    const packageDir = path.join(root, "ui/node_modules/playwright");
    mkdirSync(packageDir, { recursive: true });
    writeFileSync(path.join(root, "ui/package.json"), '{"devDependencies":{"playwright":"*"}}');
    writeFileSync(path.join(packageDir, "package.json"), '{"version":"1.62.1"}');
    const output = path.join(root, "github-output");
    const result = spawnSync("/bin/bash", ["-euo", "pipefail", "-c", browser.runs.steps[0].run], {
      cwd: root,
      encoding: "utf8",
      env: {
        ...process.env,
        CACHE_MODE: "restore",
        RUNNER_OS: "Linux",
        RUNNER_ARCH: arch,
        GITHUB_OUTPUT: output,
      },
    });
