      async (params: {
        resolveFreshSessionEntryForDelivery?: () => Promise<SessionEntry | undefined>;
      }) => {
        compactionTestState.deliveryFreshEntries.push(
          await params.resolveFreshSessionEntryForDelivery?.(),
