  afterEach(async () => {
    const storePath = compactionTestState.cfg?.session?.store;
    if (storePath) {
      await Promise.all(
        listSessionEntriesCore({ storePath }).map(({ sessionKey }) =>
          waitForSessionMaintenance(sessionKey),
